steps.content:
// turn.rs SSE 流处理
ResponseEvent::OutputItemDone(item)
// item 类型: FunctionCall
→ ToolRouter::build_tool_call(&sess, item).await?

build_tool_call() 解析:
① resolve_mcp_tool_info('shell') → None
  （非 MCP 工具）
② payload = ToolPayload::Function {
     arguments: '{"command":"cargo check"}'
   }
→ ToolCall { tool_name: 'shell', call_id: 'call_01', .. }

ToolCallRuntime::handle_tool_call(
  call: ToolCall { shell, call_01 },
  cancellation_token,
)
// parallel.rs:106
AbortOnDropHandle::new(tokio::spawn(async {
  tokio::select! {
    _ = token.cancelled() => aborted_response,
    res = dispatch(...) => res,
  }
}))

// parallel.rs:89
let supports_parallel =
  self.router.tool_supports_parallel(&call);
// → false（shell 不支持并行）

// parallel.rs:115
let _guard = if supports_parallel {
  Either::Left(lock.read().await)   // 共享锁：可多个工具并行
} else {
  Either::Right(lock.write().await) // 独占锁：shell 串行执行
};

// ShellHandler::handle(invocation)
// → handlers/shell.rs
解析参数: ShellToolCallParams {
  command: 'cargo check 2>&1 | head -20',
  workdir: None → 使用 sess.cwd,
  timeout_ms: None,
  sandbox_permissions: UseDefault,
}
// → 进入 ToolOrchestrator (ch06)

AnyToolResult {
  call_id: 'call_01',
  payload: ToolPayload::Function { .. },
  result: Box<ShellToolOutput>,
}
// registry.rs:107
→ into_response()
→ ResponseInputItem::FunctionCallOutput {
     call_id: 'call_01',
     output: '{ "output": "...", "metadata": { "exit_code": 1 } }'
   }
